{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "postpartum_return_12_week",
    "name": "12-week Postpartum Return (post-c-section, light activity)",
    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-05T00:00:00Z",
      "created_by": "personal_trainer",
      "difficulty": "adaptive",
      "language": "en",
      "estimated_duration_days": 84,
      "tags": [
        "postpartum",
        "post-c-section",
        "return-to-activity",
        "walking",
        "low-load",
        "home"
      ]
    },
    "goals": [
      {
        "id": "return_to_baseline_activity",
        "type": "primary",
        "category": "cardiovascular_endurance",
        "name": "Gradual return to regular activity and walking",
        "description": "Restore baseline daily activity and walking tolerance while protecting the C-section incision and avoiding abdominal loading until 6-week OB check.",
        "target": {
          "metric": "daily_steps",
          "target_value": 7000,
          "unit": "steps",
          "measurement_type": "relative"
        },
        "milestones": [
          {
            "id": "milestone_walk_15",
            "name": "15 minute continuous walk",
            "target_value": 15,
            "reward_points": 10
          },
          {
            "id": "milestone_walk_30",
            "name": "30 minute continuous walk",
            "target_value": 30,
            "reward_points": 25
          }
        ]
      },
      {
        "id": "restore_core_control",
        "type": "secondary",
        "category": "rehabilitation",
        "name": "Re-establish gentle core control and pelvic floor awareness",
        "description": "Gentle pelvic floor and breathing-based core activation exercises, avoiding direct abdominal strain until clearance.",
        "target": {
          "metric": "pelvic_floor_reps",
          "target_value": 10,
          "unit": "reps_daily",
          "measurement_type": "absolute"
        }
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": [
        "beginner"
      ],
      "equipment": [
        {
          "id": "yoga_mat",
          "name": "yoga mat",
          "required": false,
          "alternatives": []
        }
      ],
      "contraindications": [
        {
          "condition": "acog:postpartum_c_section_until_6_weeks",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "core_loading",
            "abdominal_crunches",
            "heavy_lifting"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 6,
        "min_minutes_per_day": 10,
        "max_minutes_per_day": 45
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "user.ob_cleared_6_week",
          "type": "boolean",
          "source": "user.ob_clearance",
          "label": "OB clearance for heavy lifting/abs at 6 weeks"
        },
        {
          "id": "user.pain_with_movement",
          "type": "boolean",
          "source": "user.pain_with_movement",
          "label": "Pain during movement"
        },
        {
          "id": "user.fatigue_level",
          "type": "number",
          "source": "wellness.subjective_readiness",
          "label": "Daily fatigue/readiness (0-10)"
        }
      ],
      "rules": [
        {
          "id": "rule_wait_clearance_for_core_load",
          "condition": {
            "field": "user.ob_cleared_6_week",
            "op": "eq",
            "value": false
          },
          "actions": [
            {
              "type": "modify",
              "scope": "plan",
              "note": "Keep core-loading exercises as gentle activation and breathing; omit heavy/core-loading activities until clearance."
            }
          ]
        },
        {
          "id": "rule_skip_on_pain",
          "condition": {
            "field": "user.pain_with_movement",
            "op": "eq",
            "value": true
          },
          "actions": [
            {
              "type": "modify",
              "scope": "day",
              "note": "Recommend rest/medical review and substitute with gentle walking and breathwork."
            }
          ]
        }
      ]
